using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DicesList", menuName = "Data/Battle/Dice System/Dices List")]
public class DicesList : ScriptableObject
{
	public List<Dice> dice = new List<Dice>();

	private Dictionary<string, string> diceNameTransformerDictionary = new Dictionary<string, string>
	{
		{ "LinkBoostS", "LinkBoost" },
		{ "LinkEmpowerS", "LinkEmpower" },
		{ "LinkRockPlateS", "LinkRockPlate" },
		{ "LinkVorpalPlateS", "LinkVorpalPlate" },
		{ "Link:Boost", "LinkBoost" },
		{ "Link:Empower", "LinkEmpower" },
		{ "Link:RockPlate", "LinkRockPlate" },
		{ "Link:VorpalPlate", "LinkVorpalPlate" },
		{ "owl-light", "owllight" },
		{ "UnstableScrapping", "EnduringScrapping" },
		{ "OverloadedRepair", "EnduringRepair" },
		{ "ClamourPact", "ClamorPact" },
		{ "InnerPiece", "InnerPeace" },
		{ "ShamanicComtemplation", "ShamanicContemplation" }
	};

	public virtual Dice GetDice(string name)
	{
		name = ReplaceDiceNameTransformed(name);
		for (int i = 0; i < dice.Count; i++)
		{
			if (name == dice[i].name.ToLower())
			{
				return dice[i];
			}
		}
		return null;
	}

	protected string ReplaceDiceNameTransformed(string name)
	{
		name = name.ToLower().Replace(" ", "");
		foreach (KeyValuePair<string, string> item in diceNameTransformerDictionary)
		{
			if (name.Contains(item.Key.ToLower()))
			{
				name = name.Replace(item.Key.ToLower(), item.Value.ToLower());
			}
		}
		return name;
	}

	public bool CheckDiscoveredDiceWithDiceNameTransformed(List<string> discoveredDiceSaveString)
	{
		bool result = false;
		foreach (KeyValuePair<string, string> item in diceNameTransformerDictionary)
		{
			if (discoveredDiceSaveString.Contains(item.Key))
			{
				discoveredDiceSaveString.Remove(item.Key);
				discoveredDiceSaveString.Add(item.Value);
				result = true;
			}
		}
		return result;
	}
}
